        assertEquals("milk · eggs", NoteText.preview("# Shopping\n- [ ] milk\n\n- [x] eggs"))
        assertEquals(NoteText.UNTITLED, NoteText.title("  \n"))
        assertEquals(NoteLabel.NONE, NoteLabel.GREEN.next())
    }
